//! `pack`: the real binary, end to end. Keys are generated by the binary at test time; every
//! command's output is scanned for every secret generated so far. The release a run writes is read
//! back the way a client reads it: `keys.json` under the config's root, a feed signed in-test that
//! points at the manifest, then `verify_manifest`, the pack's hash and `decode_verified` on every
//! frame, whose output must equal the input file.
//!
//! Each run gets its own temp dir (`TMPDIR`, `TMP`, `TEMP`), so the work-dir count of one test is
//! not disturbed by another running in parallel.

mod common;

use std::cell::RefCell;
use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Output;

use common::*;
use ed25519_dalek::SigningKey;
use ed25519_dalek::pkcs8::DecodePrivateKey;
use lunepack_codec_lzma::LzmaCodec;
use lunepack_core::digest::U53;
use lunepack_core::{
    AppId, ArtifactRef, Channel, Clock, ClockReading, CodecId, Hasher, PayloadKind, ReleaseDoc,
    RollbackFloor, Signer, Target, TrustedRoot, VerifiedEntry, VerifiedKeySet, VerifiedManifest,
    decode_verified, next_feed, sign_envelope, verify_feed, verify_key_set, verify_manifest,
};
use lunepack_crypto::{Ed25519Signer, Ed25519Verifier, Sha256Hasher};
use lunepack_testkit::exe_headers;

const APP: &str = "org.example.hello";
const T0: u64 = 1_800_000_000;
const DAY: u64 = 86_400;
const WORK_PREFIX: &str = "lunepack-pack-";

struct At(u64);

impl Clock for At {
    fn now_unix_secs(&self) -> u64 {
        self.0
    }
}

struct Key {
    path: PathBuf,
    public: String,
}

fn s(path: &Path) -> &str {
    path.to_str().expect("utf-8 path")
}

fn hex(text: &str) -> [u8; 32] {
    let bytes: Vec<u8> = (0..32)
        .map(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).unwrap())
        .collect();
    bytes.try_into().unwrap()
}

fn spec(k: &Key) -> String {
    format!("file:{}", s(&k.path))
}

/// A config with one root key, and release dirs whose `keys.json` lists `release` keys.
struct World {
    dir: tempfile::TempDir,
    config: PathBuf,
    tmp: PathBuf,
    root: Key,
    release: Vec<Key>,
    threshold: u64,
    secrets: RefCell<Vec<Vec<u8>>>,
}

/// One `pack` invocation.
struct Pack<'a> {
    input: &'a Path,
    version: &'a str,
    target: &'a str,
    release_dir: &'a Path,
    signers: Vec<String>,
    epoch: u64,
    extra: Vec<&'a str>,
}

impl World {
    /// `release_keys` keys, `threshold` of them needed; `keys_extra` goes to `keys set`.
    fn new(release_keys: usize, threshold: u64) -> World {
        let dir = tempfile::tempdir().unwrap();
        let tmp = dir.path().join("tmp");
        fs::create_dir(&tmp).unwrap();
        let mut w = World {
            config: dir.path().join("lunepack.toml"),
            tmp,
            root: Key {
                path: PathBuf::new(),
                public: String::new(),
            },
            release: Vec::new(),
            threshold,
            secrets: RefCell::new(Vec::new()),
            dir,
        };
        w.root = w.new_key("root");
        w.release = (0..release_keys)
            .map(|i| w.new_key(&format!("release{i}")))
            .collect();
        let out = w.run(
            &["init", "--app-id", APP, "--root-key", &w.root.public],
            &[],
        );
        assert_ok(&out, "init");
        w
    }

    fn cmd(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let output = run(args, env);
        let secrets = self.secrets.borrow();
        let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
        assert_no_secrets(&output, &refs);
        output
    }

    fn run(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let mut full = vec!["--config", s(&self.config)];
        full.extend_from_slice(args);
        self.cmd(&full, env)
    }

    fn new_key(&self, name: &str) -> Key {
        let base = self.dir.path().join(name);
        let out = self.cmd(&["keys", "gen", s(&base)], &[]);
        assert_ok(&out, "keys gen");
        let path = base.with_extension("key");
        let pem = fs::read_to_string(&path).unwrap();
        let seed = SigningKey::from_pkcs8_pem(&pem).unwrap().to_bytes();
        let mut secrets = self.secrets.borrow_mut();
        secrets.push(pem.into_bytes());
        secrets.push(seed.to_vec());
        Key {
            path,
            public: field(&stdout(&out), "public:"),
        }
    }

    /// A release dir named `name` with `keys.json` written at `T0`. Each release dir has its own
    /// publisher state file (a copy of the config in `<name>.publisher/`): one state file records
    /// one release dir, and a second dir without the recorded `keys.json` is refused.
    fn release_dir(&self, name: &str, keys_extra: &[&str]) -> PathBuf {
        let dir = self.dir.path().join(name);
        fs::create_dir(&dir).unwrap();
        let publisher = self.dir.path().join(format!("{name}.publisher"));
        fs::create_dir(&publisher).unwrap();
        let config = publisher.join("lunepack.toml");
        fs::copy(&self.config, &config).unwrap();
        let t = self.threshold.to_string();
        let mut args = vec![
            "--config",
            s(&config),
            "keys",
            "set",
            "--release-dir",
            s(&dir),
            "--threshold",
            &t,
        ];
        for k in &self.release {
            args.extend_from_slice(&["--release-key", &k.public]);
        }
        let root = spec(&self.root);
        args.extend_from_slice(&["--sign", &root]);
        args.extend_from_slice(keys_extra);
        let out = self.cmd(&args, &[("SOURCE_DATE_EPOCH", &T0.to_string())]);
        assert_ok(&out, "keys set");
        dir
    }

    fn all_signers(&self) -> Vec<String> {
        self.release.iter().map(spec).collect()
    }

    fn pack(&self, p: &Pack<'_>) -> Output {
        self.pack_with_tmp(p, &self.tmp)
    }

    fn pack_with_tmp(&self, p: &Pack<'_>, tmp: &Path) -> Output {
        let mut args = vec![
            "pack",
            "--input",
            s(p.input),
            "--version",
            p.version,
            "--target",
            p.target,
            "--release-dir",
            s(p.release_dir),
        ];
        for signer in &p.signers {
            args.extend_from_slice(&["--sign", signer]);
        }
        args.extend_from_slice(&p.extra);
        let epoch = p.epoch.to_string();
        let tmp = s(tmp);
        self.run(
            &args,
            &[
                ("SOURCE_DATE_EPOCH", &epoch),
                ("TMPDIR", tmp),
                ("TMP", tmp),
                ("TEMP", tmp),
            ],
        )
    }

    fn work_dirs(&self) -> usize {
        fs::read_dir(&self.tmp)
            .unwrap()
            .filter(|e| {
                e.as_ref()
                    .unwrap()
                    .file_name()
                    .to_string_lossy()
                    .starts_with(WORK_PREFIX)
            })
            .count()
    }

    fn keys(&self, release_dir: &Path) -> VerifiedKeySet {
        let root = TrustedRoot::from_parts(
            AppId::parse(APP).unwrap(),
            1,
            1,
            &[hex(&self.root.public)],
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .unwrap();
        verify_key_set(
            &root,
            &fs::read(release_dir.join("keys.json")).unwrap(),
            &RollbackFloor::default(),
            &ClockReading::read(&At(T0), None),
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .expect("keys.json verifies")
    }

    /// Reads a release the way a client does and returns the manifest and every decoded file.
    fn verify(
        &self,
        release_dir: &Path,
        version: &str,
        target: Target,
    ) -> (VerifiedManifest, BTreeMap<String, Vec<u8>>) {
        let keys = self.keys(release_dir);
        let base = release_dir.join(version);
        let manifest = fs::read(base.join(format!("{}.manifest.json", target.as_str()))).unwrap();
        let pack = fs::read(base.join(format!("{}.pack", target.as_str()))).unwrap();
        let app = AppId::parse(APP).unwrap();
        let channel = Channel::parse("stable").unwrap();
        let release = ReleaseDoc {
            version: version.to_owned(),
            targets: BTreeMap::from([(
                target.as_str().to_owned(),
                ArtifactRef {
                    path: format!("{version}/{}.manifest.json", target.as_str()),
                    size: U53::new(manifest.len() as u64).unwrap(),
                    sha256: Sha256Hasher.sha256(&manifest),
                },
            )]),
            rollout: None,
        };
        let feed = next_feed(None, &app, &channel, T0, vec![release], None).unwrap();
        let signers: Vec<Ed25519Signer> = self
            .release
            .iter()
            .map(|k| Ed25519Signer::from_key_file(&k.path).unwrap())
            .collect();
        let refs: Vec<&dyn Signer> = signers.iter().map(|s| s as &dyn Signer).collect();
        let feed_bytes = sign_envelope(
            PayloadKind::Feed,
            &feed.to_payload(),
            &refs,
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .unwrap();
        let feed = verify_feed(
            &keys,
            &feed_bytes,
            &app,
            &channel,
            &RollbackFloor::default(),
            &ClockReading::read(&At(T0), None),
            &Ed25519Verifier,
        )
        .unwrap();
        let entry = feed.target_entry(0, target).unwrap();
        let verified = verify_manifest(&keys, &entry, &manifest, &Sha256Hasher, &Ed25519Verifier)
            .expect("the manifest verifies");
        verified.pack().check_bytes(&pack, &Sha256Hasher).unwrap();
        let mut files = BTreeMap::new();
        for e in verified.entries() {
            if let VerifiedEntry::File { path, frame, .. } = e {
                let mut out = Vec::new();
                if let Some(f) = frame {
                    let start = f.offset() as usize;
                    let bytes = &pack[start..start + f.length() as usize];
                    decode_verified(f, bytes, &Sha256Hasher, &LzmaCodec, &mut out)
                        .expect("the frame decodes");
                }
                files.insert(path.as_str().to_owned(), out);
            }
        }
        (verified, files)
    }
}

fn file_entry<'a>(m: &'a VerifiedManifest, path: &str) -> &'a VerifiedEntry {
    m.entries()
        .iter()
        .find(|e| e.path().as_str() == path)
        .unwrap_or_else(|| panic!("no entry {path}"))
}

fn codec_of(m: &VerifiedManifest, path: &str) -> Option<CodecId> {
    match file_entry(m, path) {
        VerifiedEntry::File { frame, .. } => frame.as_ref().map(|f| f.codec()),
        _ => panic!("{path} is not a file"),
    }
}

#[cfg(unix)]
fn exec_of(m: &VerifiedManifest, path: &str) -> bool {
    match file_entry(m, path) {
        VerifiedEntry::File { exec, .. } => *exec,
        _ => panic!("{path} is not a file"),
    }
}

/// Deterministic noise (xorshift64), incompressible.
fn noise(seed: u64, len: usize) -> Vec<u8> {
    let mut x = seed | 1;
    (0..len)
        .map(|_| {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            (x >> 24) as u8
        })
        .collect()
}

fn text(len: usize) -> Vec<u8> {
    b"The quick brown fox jumps over the lazy dog; pack me small.\n"
        .iter()
        .copied()
        .cycle()
        .take(len)
        .collect()
}

fn png(len: usize) -> Vec<u8> {
    let mut v = vec![0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];
    v.extend(noise(7, len));
    v
}

fn write(root: &Path, rel: &str, bytes: &[u8]) {
    let path = root.join(rel);
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(path, bytes).unwrap();
}

#[cfg(unix)]
fn set_mode(path: &Path, mode: u32) {
    use std::os::unix::fs::PermissionsExt;
    fs::set_permissions(path, fs::Permissions::from_mode(mode)).unwrap();
}

/// The host's own target, where symlinks and exec bits exist on Unix.
fn host_target() -> &'static str {
    if cfg!(windows) {
        "windows-x86_64"
    } else {
        "linux-x86_64"
    }
}

/// Test 2's tree: nested dirs, an empty dir, an empty file, two identical files, a PNG, this test
/// binary, a text file; on Unix an exec bit and a symlink.
fn mixed_tree(root: &Path) {
    write(root, "docs/guide/intro.txt", &text(20_000));
    write(root, "docs/guide/copy-a.txt", &text(9_000));
    write(root, "shared/copy-b.txt", &text(9_000));
    write(root, "empty.dat", b"");
    write(root, "assets/logo.png", &png(4_000));
    fs::create_dir_all(root.join("empty-dir")).unwrap();
    let exe = std::env::current_exe().expect("current_exe");
    fs::create_dir_all(root.join("bin")).unwrap();
    fs::copy(&exe, root.join("bin/app")).unwrap();
    write(root, "bin/run.sh", b"#!/bin/sh\nexec ./app \"$@\"\n");
    #[cfg(unix)]
    {
        set_mode(&root.join("bin/run.sh"), 0o755);
        set_mode(&root.join("docs/guide/intro.txt"), 0o644);
        std::os::unix::fs::symlink("docs/guide/intro.txt", root.join("readme")).unwrap();
    }
}

fn read_input(root: &Path, rel: &str) -> Vec<u8> {
    fs::read(root.join(rel)).unwrap()
}

#[test]
fn the_secret_scan_fires_on_every_form() {
    self_check_secret_scan();
}

/// Tests 1, 2 and 4: one input packed with one worker and with four (the second with a 1 MiB
/// budget, so every job is admitted alone) gives byte-identical packs and manifests; the manifest
/// holds what the tree holds; no work dir is left behind.
#[test]
fn pack_is_deterministic_and_complete() {
    let w = World::new(1, 1);
    let input = tempfile::tempdir().unwrap();
    mixed_tree(input.path());
    let (a, b) = (w.release_dir("a", &[]), w.release_dir("b", &[]));
    assert_eq!(w.work_dirs(), 0);

    let target = host_target();
    let first = w.pack(&Pack {
        input: input.path(),
        version: "1.2.3",
        target,
        release_dir: &a,
        signers: w.all_signers(),
        epoch: T0,
        extra: vec!["--jobs", "1"],
    });
    assert_ok(&first, "pack --jobs 1");
    let out = stdout(&first);
    for stage in [
        "assemble:",
        "code-sign:",
        "hash:",
        "pack:",
        "sign:",
        "verify:",
        "placed:",
        "totals:",
    ] {
        assert!(out.contains(stage), "no {stage} line in {out:?}");
    }
    assert_eq!(w.work_dirs(), 0, "the work dir is removed after success");

    let second = w.pack(&Pack {
        input: input.path(),
        version: "1.2.3",
        target,
        release_dir: &b,
        signers: w.all_signers(),
        epoch: T0,
        extra: vec!["--jobs", "4", "--memory-budget-mib", "1"],
    });
    assert_ok(&second, "pack --jobs 4 --memory-budget-mib 1");
    // And truly in parallel: four workers under the default budget.
    let c = w.release_dir("c", &[]);
    let third = w.pack(&Pack {
        input: input.path(),
        version: "1.2.3",
        target,
        release_dir: &c,
        signers: w.all_signers(),
        epoch: T0,
        extra: vec!["--jobs", "4"],
    });
    assert_ok(&third, "pack --jobs 4");
    for name in [
        format!("1.2.3/{target}.pack"),
        format!("1.2.3/{target}.manifest.json"),
    ] {
        let first = fs::read(a.join(&name)).unwrap();
        for other in [&b, &c] {
            assert_eq!(
                first,
                fs::read(other.join(&name)).unwrap(),
                "{name} differs from the --jobs 1 run"
            );
        }
    }

    let target = Target::parse(target).unwrap();
    let (m, files) = w.verify(&a, "1.2.3", target);
    assert_eq!(m.issued(), T0);
    // Every file decodes to the input's bytes.
    for (path, bytes) in &files {
        assert_eq!(bytes, &read_input(input.path(), path), "{path}");
    }
    assert!(files.contains_key("empty.dat"));
    assert_eq!(codec_of(&m, "empty.dat"), None);
    assert_eq!(codec_of(&m, "assets/logo.png"), Some(CodecId::Stored));
    assert_eq!(codec_of(&m, "docs/guide/intro.txt"), Some(CodecId::Lzma2));
    assert!(
        matches!(
            codec_of(&m, "bin/app"),
            Some(CodecId::BcjX86Lzma2 | CodecId::BcjArm64Lzma2 | CodecId::Bcj2)
        ),
        "the test binary gets a BCJ codec: {:?}",
        codec_of(&m, "bin/app")
    );
    // Identical files share one frame.
    let frame = |p: &str| match file_entry(&m, p) {
        VerifiedEntry::File { frame, .. } => frame.clone().unwrap(),
        _ => unreachable!(),
    };
    assert_eq!(
        frame("docs/guide/copy-a.txt").offset(),
        frame("shared/copy-b.txt").offset()
    );
    for dir in ["docs", "docs/guide", "shared", "assets", "bin", "empty-dir"] {
        assert!(
            matches!(file_entry(&m, dir), VerifiedEntry::Dir { .. }),
            "{dir} is a dir entry"
        );
    }
    #[cfg(unix)]
    {
        assert!(exec_of(&m, "bin/run.sh"));
        assert!(!exec_of(&m, "docs/guide/intro.txt"));
        assert!(matches!(
            file_entry(&m, "readme"),
            VerifiedEntry::Symlink { target, .. } if target == "docs/guide/intro.txt"
        ));
    }
}

/// Test 3 (and test 4's failure half): every refusal exits 1, writes nothing and leaves no work
/// dir.
#[test]
fn refusals() {
    // Two release keys, both needed; their windows end 365 days after T0.
    let not_after = (T0 + 365 * DAY).to_string();
    let w = World::new(2, 2);
    let dir = w.release_dir("rel", &["--not-after", &not_after]);
    let input = tempfile::tempdir().unwrap();
    write(input.path(), "a.txt", &text(3_000));
    let target = host_target();
    let base = |version: &'static str| Pack {
        input: input.path(),
        version,
        target,
        release_dir: &dir,
        signers: w.all_signers(),
        epoch: T0,
        extra: Vec::new(),
    };
    let refused = |p: &Pack<'_>, what: &str, needle: &str| {
        let out = w.pack(p);
        let err = assert_fails(&out, 1, what);
        assert!(err.contains(needle), "{what}: {err:?} lacks {needle:?}");
        assert!(
            !dir.join(p.version)
                .join(format!("{}.manifest.json", p.target))
                .exists()
                || p.version == "1.0.0",
            "{what}: nothing is written"
        );
        assert_eq!(w.work_dirs(), 0, "{what}: no work dir is left");
    };

    assert_ok(&w.pack(&base("1.0.0")), "first pack");
    refused(&base("1.0.0"), "an existing manifest", "already exists");

    let mut p = base("2.0.0");
    p.signers = vec![spec(&w.root), spec(&w.release[0])];
    refused(&p, "a signer not in the key set", "not in keys.json");

    let mut p = base("2.0.0");
    p.epoch = T0 + 400 * DAY;
    refused(&p, "a signer outside its window", "is not valid at");

    let mut p = base("2.0.0");
    p.signers = vec![spec(&w.release[0])];
    refused(&p, "too few signers", "needs 2 release signer(s), 1 given");

    let mut p = base("2.0.0");
    p.extra = vec!["--app-id", "org.example.other"];
    refused(&p, "another app id", "is not the config's app id");

    assert_ok(&w.pack(&base("1.1.0+build.1")), "pack 1.1.0+build.1");
    refused(
        &base("1.1.0+build.2"),
        "equal precedence, other text",
        "of equal precedence",
    );

    #[cfg(unix)]
    {
        let links = tempfile::tempdir().unwrap();
        write(links.path(), "a.txt", b"x");
        std::os::unix::fs::symlink("a.txt", links.path().join("link")).unwrap();
        let mut p = base("3.0.0");
        p.input = links.path();
        p.target = "windows-x86_64";
        refused(&p, "a symlink on a Windows target", "cannot be packed");

        let fifo = tempfile::tempdir().unwrap();
        write(fifo.path(), "a.txt", b"x");
        let made = std::process::Command::new("mkfifo")
            .arg(fifo.path().join("pipe"))
            .status()
            .expect("run mkfifo");
        assert!(made.success(), "mkfifo");
        let mut p = base("3.0.0");
        p.input = fifo.path();
        refused(&p, "a special file", "special file");
    }
    #[cfg(windows)]
    {
        let mut p = base("3.0.0");
        p.target = "linux-x86_64";
        refused(&p, "a Unix target on a Windows host", "Windows host");
    }
}

/// The work-dir count is a real instrument: the binary does create its work dir under `TMPDIR`
/// (`TMP` on Windows), since a missing one makes the run fail.
#[test]
fn work_dir_goes_under_the_temp_dir() {
    let w = World::new(1, 1);
    let dir = w.release_dir("rel", &[]);
    let input = tempfile::tempdir().unwrap();
    write(input.path(), "a.txt", b"hello");
    let missing = w.dir.path().join("no-such-tmp");
    let out = w.pack_with_tmp(
        &Pack {
            input: input.path(),
            version: "1.0.0",
            target: host_target(),
            release_dir: &dir,
            signers: w.all_signers(),
            epoch: T0,
            extra: Vec::new(),
        },
        &missing,
    );
    let err = assert_fails(&out, 1, "pack with a missing temp dir");
    assert!(err.contains("work dir"), "{err:?}");
}

/// Test 5 (M3-D13): an ordinary non-Rust app's build output, no Cargo file anywhere.
#[test]
fn non_rust_app_layout() {
    let w = World::new(1, 1);
    let dir = w.release_dir("rel", &[]);
    let input = tempfile::tempdir().unwrap();
    let root = input.path();
    write(root, "MyApp.exe", &exe_headers::pe(0x8664, 96 * 1024));
    write(
        root,
        "lib/libfoo.so",
        &exe_headers::elf(183, false, 64 * 1024),
    );
    write(root, "bin/helper.dll", &exe_headers::pe(0xAA64, 64 * 1024));
    write(root, "assets/logo.png", &png(8_000));
    write(
        root,
        "assets/data.json",
        &br#"{"name": "MyApp", "items": [1, 2, 3], "nested": {"ok": true}}"#.repeat(40),
    );
    write(root, "assets/fonts/ui/Regular.txt", &text(5_000));
    write(root, "README.txt", &text(2_500));
    let mut stack = vec![root.to_path_buf()];
    while let Some(d) = stack.pop() {
        for e in fs::read_dir(&d).unwrap() {
            let e = e.unwrap();
            assert!(!e.file_name().to_string_lossy().starts_with("Cargo."));
            if e.file_type().unwrap().is_dir() {
                stack.push(e.path());
            }
        }
    }

    let pack = |target: &'static str| {
        w.pack(&Pack {
            input: root,
            version: "4.0.0",
            target,
            release_dir: &dir,
            signers: w.all_signers(),
            epoch: T0,
            extra: Vec::new(),
        })
    };
    let check = |target: Target| {
        let (m, files) = w.verify(&dir, "4.0.0", target);
        for (path, bytes) in &files {
            assert_eq!(bytes, &read_input(root, path), "{path}");
        }
        assert!(
            matches!(
                codec_of(&m, "MyApp.exe"),
                Some(CodecId::BcjX86Lzma2 | CodecId::Bcj2)
            ),
            "MyApp.exe: {:?}",
            codec_of(&m, "MyApp.exe")
        );
        assert_eq!(codec_of(&m, "lib/libfoo.so"), Some(CodecId::BcjArm64Lzma2));
        assert_eq!(codec_of(&m, "bin/helper.dll"), Some(CodecId::BcjArm64Lzma2));
        assert_eq!(codec_of(&m, "assets/logo.png"), Some(CodecId::Stored));
        for p in [
            "assets/data.json",
            "assets/fonts/ui/Regular.txt",
            "README.txt",
        ] {
            assert_eq!(codec_of(&m, p), Some(CodecId::Lzma2), "{p}");
        }
        assert!(matches!(
            file_entry(&m, "assets/fonts/ui"),
            VerifiedEntry::Dir { .. }
        ));
    };

    assert_ok(&pack("windows-x86_64"), "pack windows-x86_64");
    check(Target::WindowsX86_64);

    let linux = pack("linux-aarch64");
    if cfg!(windows) {
        let err = assert_fails(&linux, 1, "linux-aarch64 on a Windows host");
        assert!(err.contains("Windows host"), "{err:?}");
    } else {
        assert_ok(&linux, "pack linux-aarch64");
        check(Target::LinuxAarch64);
    }
}
